package com.pulsepay.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.time.*; import java.util.concurrent.*; import org.springframework.core.annotation.Order; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
@Component @Order(1) public class RateLimitFilter extends OncePerRequestFilter { private final ConcurrentHashMap<String,Bucket> fallback=new ConcurrentHashMap<>(); private final StringRedisTemplate redis; record Bucket(long window,int count){} public RateLimitFilter(StringRedisTemplate redis){this.redis=redis;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String path=r.getRequestURI();boolean credentialIssuance=path.equals("/api/v1/auth/register")||path.equals("/api/v1/auth/login")||path.equals("/api/v1/auth/refresh");if(!credentialIssuance&&!path.equals("/api/v1/refunds")){c.doFilter(r,s);return;}String key=r.getRemoteAddr()+":"+path;if(count(key)>30){s.setStatus(429);s.setContentType("application/json");s.getWriter().write("{\"error\":{\"code\":\"RATE_LIMITED\",\"message\":\"Too many requests.\"}}");return;}c.doFilter(r,s);} private long count(String key){long window=Instant.now().getEpochSecond()/60;try{String redisKey="pulsepay:rate:"+window+":"+key;Long count=redis.opsForValue().increment(redisKey);if(count!=null&&count==1)redis.expire(redisKey,Duration.ofSeconds(70));return count==null?0:count;}catch(Exception ignored){Bucket local=fallback.compute(key,(k,v)->v==null||v.window()!=window?new Bucket(window,1):new Bucket(window,v.count()+1));return local.count();}} }
